"""Bộ Medium 2: 100 câu cùng mức Medium, không lặp câu của các bộ khác.

Mỗi câu: Q(khái niệm, câu hỏi, đáp án đúng, [ba phương án nhiễu], lời giải, code=..., src=...).
Nguồn là (loại, nhãn, url). "Đề thi" khi giữ đúng ý và đáp án câu gốc, "Phỏng theo" khi đổi dữ kiện.
Mọi câu đều được diễn đạt lại và tự giải lại; đề gốc không có giấy phép dùng nguyên văn.
"""

_PRELIM = 'https://aisingapore.org/wp-content/uploads/2026/04/NOAI-2026-Preliminary-Round-Assessment-300-MCQs-Google-Forms.pdf'
_USA1 = 'https://www.usaaio.org/attachments/past-problems/2026/usaaio-2026-round-1-problems.pdf'
_MIT22 = 'https://introml.mit.edu/_static/fall22/final/review/6036_final_sp22.pdf'


def Q(topic, q, a, d, why, code=None, src=None):
    card = {'topic': topic, 'q': q, 'a': a, 'd': d, 'why': why}
    if code:
        card['code'] = code
    if src:
        card['src'] = src
    return card


def P(n, page, kind='Phỏng theo'):
    return (kind, f'NOAI 2026 Singapore · Vòng sơ loại · Câu {n}', f'{_PRELIM}#page={page}')


def U1(part, page, kind='Phỏng theo'):
    return (kind, f'USA-NA-AIO 2026 · Vòng 1 · {part}', f'{_USA1}#page={page}')


def C(exam, part, page, kind='Phỏng theo'):
    return (kind, f'CMU 10-601 · Exam {exam} Practice · {part}', f'https://www.cs.cmu.edu/~mgormley/courses/10601/handout/exam{exam}_practice_problems.pdf#page={page}')


def MIT(part, page, kind='Phỏng theo'):
    return (kind, f'MIT 6.036 · Final, Spring 2022 · {part}', f'{_MIT22}#page={page}')


def CS(n, part, page, kind='Phỏng theo'):
    return (kind, f'Stanford CS230 · Practice Midterm {n} · {part}', f'https://cs230.stanford.edu/section/6/Practice_{n}_Sol.pdf#page={page}')


def B(exam, part, page, kind='Phỏng theo'):
    url = {'Final Spring 2022': 'finals22', 'Final Spring 2023': 'finals23'}[exam]
    return (kind, f'UC Berkeley CS189 · {exam} · {part}', f'https://people.eecs.berkeley.edu/~jrs/189s23/exam/{url}.pdf#page={page}')


def T(exam, part, page, kind='Phỏng theo'):
    url = {'Final 2018': 'final_solutions', 'Midterm 2018': 'midterm_solutions'}[exam]
    return (kind, f'Toronto CSC321 · {exam} · {part}', f'https://www.cs.toronto.edu/~rgrosse/courses/csc321_2018/exams/{url}.pdf#page={page}')


